from itertools import product
Aopts=['KMP','LNP','KLN','MQR','LMQ']
Bopts=['LPQ','NPR','LMP','MNR','KNP']
Adays=[{2,7},{1,6,7},{7},{8},{2,7}]
Bdays=[{4,6},{3},{2,8},{3},{6,7,8}]
As=[a for a in product(*Aopts) if len(set(a))==5]
Bs=[b for b in product(*Bopts) if len(set(b))==5]
count=0
lo=8
hi=-1
lw=hw=None
hist={}
for a in As:
 for b in Bs:
  common=set(a)&set(b)
  if len(common)!=3 or len(common&set('KPR'))!=1: continue
  days={p:set() for p in 'KLMNPQR'}
  for p,d in zip(a,Adays): days[p].update(d)
  for p,d in zip(b,Bdays): days[p].update(d)
  n=sum(len(d)>=3 for d in days.values())
  count+=1
  hist[n]=hist.get(n,0)+1
  w={'A':''.join(a),'B':''.join(b)}
  if n<lo: lo,lw=n,w
  if n>hi: hi,hw=n,w
print({'feasible_linkages':count,'bounds':[lo,hi],'low_witness':lw,'high_witness':hw,'decision':'confirmed' if lo>=4 else 'excluded' if hi<4 else 'undetermined'})
print('histogram',hist)
# Independent witness check using a per-date set of attendees, rather than unions per person.
for w,expected in [(lw,lo),(hw,hi)]:
 bydate={d:set() for d in range(1,9)}
 for label,opts,dates in [('A',Aopts,Adays),('B',Bopts,Bdays)]:
  assert len(set(w[label]))==5
  for p,o,ds in zip(w[label],opts,dates):
   assert p in o
   for d in ds: bydate[d].add(p)
 assert len(set(w['A'])&set(w['B']))==3
 assert len(set(w['A'])&set(w['B'])&set('KPR'))==1
 totals={p:sum(p in attendees for attendees in bydate.values()) for p in 'KLMNPQR'}
 assert sum(v>=3 for v in totals.values())==expected
 print(w, totals)

