from itertools import product
optsA=['KMP','LNP','KLN','MQR','LMQ']
optsB=['LPQ','NPR','LMP','MNR','KNP']
datesA=[{2,7},{1,6,7},{7},{8},{2,7}]
datesB=[{4,6},{3},{2,8},{3},{6,7,8}]
results=[]
for a in product(*optsA):
 if a[0]!='M' or len(set(a))!=5: continue
 for b in product(*optsB):
  if len(set(b))!=5 or a[1]!=b[3]: continue
  common=set(a)&set(b)
  if len(common)!=3 or len(common&set('KPR'))!=1: continue
  attendance={p:set() for p in 'KLMNPQR'}
  for p,ds in list(zip(a,datesA))+list(zip(b,datesB)):
   attendance[p].update(ds)
  score=sum(len(ds)>=3 for ds in attendance.values())
  results.append((score, ''.join(a), ''.join(b)))
low=min(results,key=lambda r:r[0]); high=max(results,key=lambda r:r[0])
# Independently verify endpoints by counting distinct dates with each person present.
for row in [low,high]:
 score,a,b=row
 assert a[0]=='M' and a[1]==b[3]=='N' # Intersection of A2 and B4 candidates is N.
 bydate={d:set() for d in range(1,9)}
 for letters,dslist in [(a,datesA),(b,datesB)]:
  for p,ds in zip(letters,dslist):
   for d in ds: bydate[d].add(p)
 assert sum(sum(p in attendees for attendees in bydate.values())>=3 for p in 'KLMNPQR')==score
from collections import Counter
print('histogram:',dict(Counter(r[0] for r in results)))
print({'feasible_linkages':len(results),'bounds':[low[0],high[0]],'low_witness':{'A':low[1],'B':low[2]},'high_witness':{'A':high[1],'B':high[2]},'decision':'confirmed' if low[0]>=4 else 'excluded' if high[0]<4 else 'undetermined'})

